  // ─── Services page: the four service descriptions ────────
  'servicesPage.broadcast.desc': { en: 'We produce over 200 broadcast events per year across all major sim racing titles. From single-race streams to full-season championship coverage, our team delivers broadcast-grade quality for online platforms and TV networks.', de: 'Wir produzieren über 200 Broadcast-Events pro Jahr in allen großen Simracing-Titeln. Vom einzelnen Rennstream bis zur kompletten Meisterschaftssaison liefert unser Team Broadcast-Qualität für Online-Plattformen und TV-Sender.', es: 'Producimos más de 200 eventos de transmisión al año en todos los grandes títulos de simracing. Desde streams de una sola carrera hasta la cobertura de campeonatos completos, nuestro equipo ofrece calidad de televisión para plataformas online y cadenas de TV.', pt: 'Produzimos mais de 200 eventos de transmissão por ano em todos os grandes títulos de simracing. De streams de uma única corrida à cobertura de campeonatos completos, nossa equipe entrega qualidade de broadcast para plataformas online e emissoras de TV.', fr: 'Nous produisons plus de 200 événements diffusés par an sur tous les grands titres de simracing. Du stream d’une seule course à la couverture d’un championnat complet, notre équipe livre une qualité broadcast pour les plateformes en ligne et les chaînes TV.', it: 'Produciamo oltre 200 eventi trasmessi all’anno su tutti i principali titoli di simracing. Dallo stream di una singola gara alla copertura di un intero campionato, il nostro team offre qualità broadcast per piattaforme online e reti TV.' },
  'servicesPage.broadcast.d1': { en: 'Multi-language live commentary (DE, EN, FI, DA, NO, PT, ES, KO)', de: 'Mehrsprachiger Live-Kommentar (DE, EN, FI, DA, NO, PT, ES, KO)', es: 'Comentarios en vivo multilingües (DE, EN, FI, DA, NO, PT, ES, KO)', pt: 'Comentários ao vivo em vários idiomas (DE, EN, FI, DA, NO, PT, ES, KO)', fr: 'Commentaires en direct multilingues (DE, EN, FI, DA, NO, PT, ES, KO)', it: 'Commento live multilingue (DE, EN, FI, DA, NO, PT, ES, KO)' },
  'servicesPage.broadcast.d2': { en: 'Custom graphics packages and overlays', de: 'Individuelle Grafikpakete und Overlays', es: 'Paquetes gráficos y overlays personalizados', pt: 'Pacotes gráficos e overlays personalizados', fr: 'Habillages graphiques et overlays sur mesure', it: 'Pacchetti grafici e overlay personalizzati' },
